-- Boundary Review v6.99.79 — Tier 2 Batch 5: Remaining 2-entity collisions (40 entities)

BEGIN;

-- Polish-Lithuanian + Cossack Hetmanate (62/678)
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 800000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 800000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.7), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/plc-fix] Polish-Lithuanian Commonwealth (1569 Union of Lublin - 1795 Third Partition) — peak ~1M km² covered modern Poland + Lithuania + Belarus + most of Ukraine + parts of Latvia + Estonia + Russia. Replaced shared polygon with 800km circle around Warsaw.' WHERE id = 62;
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 400000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 400000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.6), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/hetmanate-fix] Cossack Hetmanate (Гетьманщина, 1649-1764) was a Ukrainian Cossack state founded by Bohdan Khmelnytsky after Khmelnytsky Uprising; Pereiaslav Agreement 1654 made it Russian protectorate; abolished by Catherine II 1764.' WHERE id = 678;

-- Seljuk + Crusader Edessa (122/473)
UPDATE geo_entities SET ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2-seljuk-note] LEGITIMATE Great Seljuk polygon. 473 Edessa (Crusader) erroneously shared this — corrected.' WHERE id = 122;
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 120000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 120000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.6), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/edessa-fix] County of Edessa (Comitatus Edessanus, 1098-1144) was the first Crusader state, founded by Baldwin of Boulogne in Upper Mesopotamia; fell to Zengid Imad ad-Din 1144 triggering Second Crusade.' WHERE id = 473;

-- Ancestral Puebloans + Pueblo (204/223) — same culture different periods
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 250000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 250000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.6), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/puebloan-fix] Ancestral Puebloans (Anasazi tradition, 100 CE - 1280) covered Four Corners region of US Southwest, peak under Chaco Canyon + Mesa Verde phenomena. NOTE: same culture as Pueblo (id=223) but different period — duplicate consolidation candidate.' WHERE id = 204;
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 250000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 250000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.55), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/pueblo-fix] Pueblo (-750 to present) Basketmaker through Pueblo IV phases of US Southwest indigenous peoples (Hopi, Zuni, Acoma, Tewa, Tiwa, Towa, Keres). Same continuous culture as Ancestral Puebloans (id=204); recommend merge.' WHERE id = 223;

-- Virreinato del Peru DUPLICATES (206/709)
