UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 400000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 400000)::geometry), boundary_source = 'approximate_circle', boundary_ne_iso_a3 = NULL, confidence_score = LEAST(confidence_score, 0.55), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/teda-fix] Teda (Tubu) confederation — Nilo-Saharan speakers of Tibesti Mountains + Borkou + Ennedi (N Chad + S Libya); pastoral nomadic confederation with caravan trade; never unified into single state; later targets of French/Italian colonialism.' WHERE id = 841;

-- Indian (588/589)
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 400000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 400000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.65), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/chalukya-fix] Western Chalukya Empire (Kalyani Chalukyas, 973-1189) — Karnataka-based Deccan empire successor to Rashtrakutas; capital Manyakheta then Kalyani; conflict with Cholas + Hoysalas; literature in Kannada flourished.' WHERE id = 588;
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 400000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 400000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.6), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/yadava-fix] Seuna Yadava dynasty (850-1334) — Marathi Deccan empire, capital Devagiri (modern Daulatabad); peak 13th c. controlled most of modern Maharashtra + N Karnataka + S Gujarat + parts of MP/AP; conquered by Delhi Sultanate (Khilji).' WHERE id = 589;

-- W African (851 Oyo, 852 Sokoto)
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 400000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 400000)::geometry), boundary_source = 'approximate_circle', boundary_ne_iso_a3 = NULL, confidence_score = LEAST(confidence_score, 0.65), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/oyo-fix] Oyo Empire (1300-1896) — Yoruba empire in SW Nigeria, peak 17th-18th c.; major slave-trade participant; capital Oyo-Ile; civil war + Fulani jihad caused decline; British annexation 1896.' WHERE id = 851;
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 700000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 700000)::geometry), boundary_source = 'approximate_circle', boundary_ne_iso_a3 = NULL, confidence_score = LEAST(confidence_score, 0.75), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/sokoto-fix] Sokoto Caliphate (Daular Usmaniyya, 1804-1903) — Fulani jihad state founded by Uthman dan Fodio; covered most of N Nigeria + parts of Cameroon, Niger, Burkina Faso; sub-emirates; largest African state of 19th c.; conquered by British 1903.' WHERE id = 852;

-- Andean (970 Salinar coast, 972 Tiahuanaco highland) — different geographies
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 80000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 80000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.55), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/salinar-fix] Salinar culture (-400 to 200 CE) was a N Peruvian coastal Andean culture (Virú+Chicama+Moche valleys), Early Intermediate Period predecessor to Moche; iron-rich Salinar pottery; absorbed by Moche.' WHERE id = 970;
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 250000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 250000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.65), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/yayamama-fix] Tiahuanaco-Chiripa-Pukara (Yaya-Mama horizon, ~800-200 BCE) was a religious tradition around Lake Titicaca (Bolivia + Peru highlands), predecessor of Tiwanaku state; stone stelae with feline/serpent/anthropomorphic iconography.' WHERE id = 972;

-- W African (983/984)
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 200000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 200000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.65), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/kaabu-fix] Kaabu Empire (Nsiiw, 1200-1867) was a Mandinka kingdom in modern Guinea-Bissau + Senegal + Gambia, founded as Mali Empire province; capital Kansala; ended by Fulani jihad (Kansala destroyed 1867).' WHERE id = 983;
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 250000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 250000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.6), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/dyolof-fix] Dyolof / Jolof confederation (pre-1549) — Wolof confederation in N Senegal, founded ~14th c.; fragmented in 1549 (Battle of Danki) into independent Wolof kingdoms (Kayor, Saalum, Siin, etc.) — see ids 728,742,843,563.' WHERE id = 984;

